(function () {
  'use strict';

  // Cegah inisialisasi ganda
  if (window.__ZYEKH_CHAT_WIDGET_LOADED__) return;
  window.__ZYEKH_CHAT_WIDGET_LOADED__ = true;

  // Baca konfigurasi dari script tag saat ini
  const currentScript = document.currentScript || document.querySelector('script[src*="chat-widget.js"]');
  const API_BASE = currentScript?.getAttribute('data-api') || (window.location.origin.includes('localhost') ? 'http://localhost:3000' : window.location.origin);
  const PERSONA = currentScript?.getAttribute('data-persona') || 'cs_store';
  const CHAT_TITLE = currentScript?.getAttribute('data-title') || (PERSONA === 'tech_mentor' ? 'Zyekh AI Mentor' : PERSONA === 'cloud_assistant' ? 'Zyekh Cloud AI' : 'Zyekh Assistant');
  const CHAT_SUBTITLE = currentScript?.getAttribute('data-subtitle') || 'Online • High-Speed AI Brain';

  const STORAGE_KEY = `zyekh_chat_${PERSONA}_history`;
  const CHAT_ID_KEY = 'zyekh_chat_user_id';

  let userId = localStorage.getItem(CHAT_ID_KEY);
  if (!userId) {
    userId = 'usr_' + Math.random().toString(36).slice(2, 11);
    localStorage.setItem(CHAT_ID_KEY, userId);
  }

  // Inject Styles
  const style = document.createElement('style');
  style.innerHTML = `
    .zyekh-chat-toggle {
      position: fixed;
      bottom: 24px;
      right: 24px;
      width: 56px;
      height: 56px;
      border-radius: 50%;
      background: #0f172a;
      color: #38bdf8;
      border: 1px solid rgba(56, 189, 248, 0.3);
      box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 999999;
      transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
    }
    .zyekh-chat-toggle:hover {
      transform: scale(1.08);
      border-color: #38bdf8;
      box-shadow: 0 12px 28px rgba(56, 189, 248, 0.25);
    }
    .zyekh-chat-toggle svg {
      width: 26px;
      height: 26px;
      fill: currentColor;
    }
    .zyekh-chat-window {
      position: fixed;
      bottom: 92px;
      right: 24px;
      width: 380px;
      height: 540px;
      max-width: calc(100vw - 32px);
      max-height: calc(100vh - 120px);
      background: #090d16;
      border: 1px solid rgba(255, 255, 255, 0.12);
      border-radius: 16px;
      box-shadow: 0 20px 40px rgba(0, 0, 0, 0.6);
      display: flex;
      flex-direction: column;
      overflow: hidden;
      z-index: 999999;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      opacity: 0;
      pointer-events: none;
      transform: translateY(16px) scale(0.96);
      transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
    }
    .zyekh-chat-window.open {
      opacity: 1;
      pointer-events: auto;
      transform: translateY(0) scale(1);
    }
    .zyekh-chat-header {
      padding: 16px;
      background: #0f172a;
      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .zyekh-chat-header-info {
      display: flex;
      flex-direction: column;
      gap: 2px;
    }
    .zyekh-chat-header-title {
      font-size: 15px;
      font-weight: 600;
      color: #f8fafc;
      letter-spacing: -0.01em;
    }
    .zyekh-chat-header-status {
      font-size: 12px;
      color: #38bdf8;
      display: flex;
      align-items: center;
      gap: 6px;
    }
    .zyekh-chat-header-status::before {
      content: '';
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #38bdf8;
      box-shadow: 0 0 8px #38bdf8;
    }
    .zyekh-chat-close {
      background: transparent;
      border: none;
      color: #94a3b8;
      cursor: pointer;
      padding: 6px;
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: color 0.15s;
    }
    .zyekh-chat-close:hover {
      color: #f8fafc;
    }
    .zyekh-chat-messages {
      flex: 1;
      padding: 16px;
      overflow-y: auto;
      display: flex;
      flex-direction: column;
      gap: 12px;
      scroll-behavior: smooth;
    }
    .zyekh-chat-bubble {
      max-width: 85%;
      padding: 10px 14px;
      border-radius: 12px;
      font-size: 13.5px;
      line-height: 1.5;
      word-break: break-word;
    }
    .zyekh-chat-bubble.user {
      align-self: flex-end;
      background: #0284c7;
      color: #ffffff;
      border-bottom-right-radius: 4px;
    }
    .zyekh-chat-bubble.bot {
      align-self: flex-start;
      background: #1e293b;
      color: #e2e8f0;
      border-bottom-left-radius: 4px;
      border: 1px solid rgba(255, 255, 255, 0.05);
    }
    .zyekh-chat-bubble p {
      margin: 0 0 8px 0;
    }
    .zyekh-chat-bubble p:last-child {
      margin-bottom: 0;
    }
    .zyekh-chat-bubble code {
      background: rgba(0, 0, 0, 0.3);
      padding: 2px 5px;
      border-radius: 4px;
      font-family: monospace;
      font-size: 12px;
    }
    .zyekh-chat-bubble pre {
      background: #050811;
      padding: 8px 10px;
      border-radius: 6px;
      overflow-x: auto;
      margin: 6px 0;
    }
    .zyekh-chat-bubble a {
      color: #38bdf8;
      text-decoration: underline;
    }
    .zyekh-chat-typing {
      display: flex;
      gap: 4px;
      padding: 8px 12px;
      background: #1e293b;
      border-radius: 12px;
      align-self: flex-start;
      width: fit-content;
    }
    .zyekh-chat-typing span {
      width: 6px;
      height: 6px;
      background: #94a3b8;
      border-radius: 50%;
      animation: zyekhPulse 1.2s infinite ease-in-out;
    }
    .zyekh-chat-typing span:nth-child(2) { animation-delay: 0.2s; }
    .zyekh-chat-typing span:nth-child(3) { animation-delay: 0.4s; }
    @keyframes zyekhPulse {
      0%, 80%, 100% { transform: scale(0.6); opacity: 0.4; }
      40% { transform: scale(1); opacity: 1; }
    }
    .zyekh-chat-input-area {
      padding: 12px 14px;
      border-top: 1px solid rgba(255, 255, 255, 0.08);
      background: #0f172a;
      display: flex;
      gap: 8px;
    }
    .zyekh-chat-input {
      flex: 1;
      background: #090d16;
      border: 1px solid rgba(255, 255, 255, 0.12);
      border-radius: 8px;
      padding: 9px 12px;
      color: #f8fafc;
      font-size: 13.5px;
      outline: none;
      transition: border-color 0.15s;
    }
    .zyekh-chat-input:focus {
      border-color: #38bdf8;
    }
    .zyekh-chat-send {
      background: #0284c7;
      color: #ffffff;
      border: none;
      border-radius: 8px;
      padding: 0 14px;
      font-size: 13.5px;
      font-weight: 500;
      cursor: pointer;
      transition: background 0.15s;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .zyekh-chat-send:hover {
      background: #0369a1;
    }
    .zyekh-chat-send:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }
  `;
  document.head.appendChild(style);

  // Helper Markdown formatter
  function formatMarkdown(text) {
    if (!text) return '';
    let html = text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
    // Bold
    html = html.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
    html = html.replace(/\*(.*?)\*/g, '<strong>$1</strong>');
    // Inline code
    html = html.replace(/`([^`]+)`/g, '<code>$1</code>');
    // Links
    html = html.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
    // Newlines
    html = html.replace(/\n/g, '<br>');
    return html;
  }

  // Create UI Elements
  const toggleBtn = document.createElement('button');
  toggleBtn.className = 'zyekh-chat-toggle';
  toggleBtn.setAttribute('aria-label', 'Open Chat Assistant');
  toggleBtn.innerHTML = `
    <svg viewBox="0 0 24 24">
      <path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zm0 14H6l-2 2V4h16v12z"/>
    </svg>
  `;

  const chatWindow = document.createElement('div');
  chatWindow.className = 'zyekh-chat-window';
  chatWindow.innerHTML = `
    <div class="zyekh-chat-header">
      <div class="zyekh-chat-header-info">
        <div class="zyekh-chat-header-title">${CHAT_TITLE}</div>
        <div class="zyekh-chat-header-status">${CHAT_SUBTITLE}</div>
      </div>
      <button class="zyekh-chat-close" aria-label="Close Chat">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <line x1="18" y1="6" x2="6" y2="18"></line>
          <line x1="6" y1="6" x2="18" y2="18"></line>
        </svg>
      </button>
    </div>
    <div class="zyekh-chat-messages" id="zyekhChatMessages"></div>
    <form class="zyekh-chat-input-area" id="zyekhChatForm">
      <input type="text" class="zyekh-chat-input" id="zyekhChatInput" placeholder="Ketik pesan..." autocomplete="off" />
      <button type="submit" class="zyekh-chat-send" id="zyekhChatSend">Kirim</button>
    </form>
  `;

  document.body.appendChild(toggleBtn);
  document.body.appendChild(chatWindow);

  const messagesContainer = chatWindow.querySelector('#zyekhChatMessages');
  const chatForm = chatWindow.querySelector('#zyekhChatForm');
  const chatInput = chatWindow.querySelector('#zyekhChatInput');
  const sendBtn = chatWindow.querySelector('#zyekhChatSend');
  const closeBtn = chatWindow.querySelector('.zyekh-chat-close');

  let isOpen = false;

  function toggleChat() {
    isOpen = !isOpen;
    chatWindow.classList.toggle('open', isOpen);
    if (isOpen) {
      chatInput.focus();
      if (messagesContainer.children.length === 0) {
        appendBotMessage(
          PERSONA === 'tech_mentor'
            ? 'Hello. I am the Zyekh Technical Mentor. How can I assist with local-first tools, performance architecture, or security research today?'
            : PERSONA === 'cloud_assistant'
            ? 'Halo! Saya Zyekh Cloud Assistant. Ada file atau aset digital di Google Drive yang ingin Anda cari?'
            : 'Halo! Ada yang bisa kami bantu seputar produk akun premium atau tools AI hari ini?'
        );
      }
    }
  }

  toggleBtn.addEventListener('click', toggleChat);
  closeBtn.addEventListener('click', toggleChat);

  function appendUserMessage(text) {
    const el = document.createElement('div');
    el.className = 'zyekh-chat-bubble user';
    el.textContent = text;
    messagesContainer.appendChild(el);
    messagesContainer.scrollTop = messagesContainer.scrollHeight;
  }

  function appendBotMessage(text) {
    const el = document.createElement('div');
    el.className = 'zyekh-chat-bubble bot';
    el.innerHTML = formatMarkdown(text);
    messagesContainer.appendChild(el);
    messagesContainer.scrollTop = messagesContainer.scrollHeight;
  }

  function showTyping() {
    const typing = document.createElement('div');
    typing.className = 'zyekh-chat-typing';
    typing.id = 'zyekhTypingIndicator';
    typing.innerHTML = `<span></span><span></span><span></span>`;
    messagesContainer.appendChild(typing);
    messagesContainer.scrollTop = messagesContainer.scrollHeight;
  }

  function removeTyping() {
    const el = document.getElementById('zyekhTypingIndicator');
    if (el) el.remove();
  }

  chatForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    const text = chatInput.value.trim();
    if (!text) return;

    appendUserMessage(text);
    chatInput.value = '';
    sendBtn.disabled = true;
    showTyping();

    try {
      const res = await fetch(`${API_BASE}/api/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: text,
          chatId: userId,
          persona: PERSONA,
          channel: 'web'
        })
      });

      const data = await res.json();
      removeTyping();

      if (data && data.reply) {
        appendBotMessage(data.reply);
      } else {
        appendBotMessage('Maaf, tidak ada respon dari server.');
      }
    } catch (err) {
      removeTyping();
      appendBotMessage('[ ERROR ] Gagal terhubung ke Central AI Server. Pastikan zyekh-ai-core sedang berjalan.');
    } finally {
      sendBtn.disabled = false;
      chatInput.focus();
    }
  });
})();
